export const CHECK_COUNT = CHECKS.length;
export const AI_CHECK_COUNT = CHECKS.filter((c) => c.kind === 'ai').length;
export const RULE_BASED_CHECK_COUNT = CHECK_COUNT - AI_CHECK_COUNT;

export function getCheck(checkId) {
  return CHECKS.find((c) => c.id === checkId) || null;
}

export function getCategoryChecks(code) {
  return CHECKS.filter((c) => c.category === code);
}

export function checksByCategory() {
  const out = {};
  for (const cat of CATEGORIES) out[cat.code] = getCategoryChecks(cat.code);
  return out;
}

